<?php
namespace Tests\Feature\Students;
use App\Models\CashAccount; use App\Models\Invoice; use App\Models\InvoicePayment;
class StudentProfileFinancialSummaryTest extends StudentProfileDashboardTestCase {
 public function test_canonical_finance_summary_and_links_render_without_mutation():void { $invoice=Invoice::create(['student_id'=>$this->student->id,'academic_year_id'=>$this->enrollment->academic_year_id,'customer_name'=>$this->student->full_name,'currency'=>'EGP','subtotal_amount'=>'3000.00','total_amount'=>'3000.00','discount_amount'=>'0.00','paid_amount'=>'1000.00','remaining_amount'=>'2000.00','status'=>Invoice::STATUS_PARTIAL,'due_date'=>today()->subDay()]); $invoice->invoice_number=Invoice::numberFor($invoice->id,'2026'); $invoice->save(); $cash=CashAccount::create(['name'=>'Основная касса','type'=>'cash']); $payment=InvoicePayment::create(['invoice_id'=>$invoice->id,'cash_account_id'=>$cash->id,'amount'=>'1000.00','payment_method'=>'cash','paid_at'=>now(),'created_by'=>$this->admin->id]); $before=[$invoice->fresh()->toArray(),$payment->fresh()->toArray()]; $this->actingAs($this->admin)->get(route('dashboard.students.show',$this->student))->assertOk()->assertSee('3 000.00 EGP')->assertSee('1 000.00 EGP')->assertSee('2 000.00 EGP')->assertSee($invoice->display_number)->assertSee($payment->payment_number)->assertSee('Наличные')->assertSee('Основная касса')->assertDontSee('RUB'); $this->assertEquals($before[0],$invoice->fresh()->toArray()); $this->assertEquals($before[1],$payment->fresh()->toArray()); }
}
